"use client";
import React, { useState, useEffect } from "react";
import {
  Ruler,
  ArrowRight,
  Shirt,
  Footprints,
  Zap,
  Info,
  ChevronDown,
} from "lucide-react";
import { sizeData } from "@/data/sizes";
import { SlArrowRight } from "react-icons/sl";

export default function SizeGuidePage() {
  const [activeCat, setActiveCat] = useState<keyof typeof sizeData>("footwear");
  const [baseUnit, setBaseUnit] = useState<string>("");
  const [targetUnit, setTargetUnit] = useState<string>("");

  useEffect(() => {
    const availableUnits = sizeData[activeCat].units;
    setBaseUnit(availableUnits[0]);
    setTargetUnit(availableUnits[availableUnits.length - 1]);
  }, [activeCat]);

  const categories = [
    { id: "footwear", label: "Footwear", icon: <Footprints size={16} /> },
    { id: "apparel", label: "Apparel", icon: <Shirt size={16} /> },
    { id: "crocs", label: "Crocs", icon: <Zap size={16} /> },
  ];

  return (
    <div className="bg-background text-foreground min-h-screen pb-24 selection:bg-brand selection:text-white">
      {/* 1. EDITORIAL HEADER */}
      <header className="pt-16 pb-12 px-6 max-w-7xl mx-auto flex flex-col md:flex-row md:items-end justify-between gap-10">
        <div className="space-y-4">
          <div className="flex items-center gap-3 text-brand">
            <div className="h-[2px] w-12 bg-brand" />
            <span className="text-[11px] font-black uppercase tracking-[0.5em]">
              Global Standards
            </span>
          </div>
          <h1 className="text-7xl md:text-9xl font-black uppercase italic tracking-tighter leading-[0.8]">
            Fit <br /> <span className="opacity-20 italic">Architect</span>
          </h1>
        </div>

        <div className="max-w-70 space-y-4">
          <p className="text-[12px] font-bold uppercase leading-relaxed italic">
            Precision engineering for your silhouette. Our archive translates
            international metrics into a singular perfect fit.
          </p>
        </div>
      </header>

      {/* 2. CATEGORY SEGMENTED CONTROL */}
      <section className="px-6 mb-20">
        <div className="max-w-4xl mx-auto bg-muted/30 p-2 rounded-full border border-border flex gap-2">
          {categories.map((cat) => (
            <button
              key={cat.id}
              onClick={() => setActiveCat(cat.id as any)}
              className={`flex-1 flex items-center justify-center gap-3 py-5 rounded-full text-[11px] font-black uppercase tracking-widest transition-all duration-500 ${
                activeCat === cat.id
                  ? "bg-foreground text-background shadow-2xl scale-[1.02]"
                  : "hover:bg-muted/50"
              }`}
            >
              {cat.icon} <span>{cat.label}</span>
            </button>
          ))}
        </div>
      </section>

      <section className="max-w-5xl mx-auto px-6">
        {/* 3. CUSTOM SELECT BOXES (RADIO STYLE) */}
        <div className="grid grid-cols-1 md:grid-cols-2 gap-8 mb-12">
          <div className="space-y-4">
            <span className="text-[10px] font-black uppercase tracking-widest ml-6">
              From Size
            </span>
            <div className="grid grid-cols-2 gap-2">
              {sizeData[activeCat].units.map((u: string) => (
                <label key={u} className="relative cursor-pointer">
                  <input
                    type="radio"
                    name="baseUnit"
                    className="peer sr-only"
                    checked={baseUnit === u}
                    onChange={() => setBaseUnit(u)}
                  />
                  <div className="py-4 px-6 border-2 border-border rounded-2xl text-[10px] font-black uppercase tracking-widest text-center transition-all peer-checked:border-brand peer-checked:bg-brand/5">
                    {u}
                  </div>
                </label>
              ))}
            </div>
          </div>

          <div className="space-y-4">
            <span className="text-[10px] font-black uppercase tracking-widest ml-6">
              Target Size
            </span>
            <div className="grid grid-cols-2 gap-2">
              {sizeData[activeCat].units.map((u: string) => (
                <label key={u} className="relative cursor-pointer">
                  <input
                    type="radio"
                    name="targetUnit"
                    className="peer sr-only"
                    checked={targetUnit === u}
                    onChange={() => setTargetUnit(u)}
                  />
                  <div className="py-4 px-6 border-2 border-border rounded-2xl text-[10px] font-black uppercase tracking-widest text-center transition-all peer-checked:border-brand peer-checked:bg-brand/5">
                    {u}
                  </div>
                </label>
              ))}
            </div>
          </div>
        </div>

        {/* 4. TRANSFORMATION GRID */}
        <div className="space-y-4">
          {sizeData[activeCat].chart.map((row: any, i: number) => (
            <div
              key={i}
              className="group flex items-center justify-between bg-muted/10 border border-border rounded-4xl p-3 hover:border-foreground transition-all duration-700"
            >
              <div className="bg-background  overflow-hidden flex flex-col justify-center items-center min-w-30 md:min-w-40 text-center shadow-sm">
                <span className="text-xl md:text-5xl font-black italic tracking-tighter">
                  {String(row[baseUnit])}
                </span>
                <p className="text-[8px] font-black uppercase tracking-[0.2em] mt-2 opacity-50">
                  {baseUnit}
                </p>
              </div>

              <div className="flex flex-col items-center gap-2 md:opacity-10 group-hover:opacity-100 group-hover:text-brand transition-all duration-700">
                <ArrowRight size={24} strokeWidth={3} />
              </div>

              <div className="bg-background  overflow-hidden flex flex-col justify-center items-center min-w-30 md:min-w-40 text-center shadow-sm">
                <span className="text-xl md:text-5xl font-black italic tracking-tighter">
                  {String(row[targetUnit])}
                </span>
                <p className="text-[8px] font-black uppercase tracking-[0.2em] mt-2 opacity-50">
                  {targetUnit}
                </p>
              </div>
            </div>
          ))}
        </div>

        {/* 5. LEGAL & BRAND DISCLAIMER */}
        <div className="relative group overflow-hidden rounded-4xl bg-foreground text-background p-12 md:p-20 my-10">
          <div className="absolute -right-20 -bottom-20 opacity-10 group-hover:rotate-12 transition-transform duration-1000">
            <Ruler size={400} />
          </div>

          <div className="relative z-10 grid grid-cols-1 md:grid-cols-2 gap-12 items-center">
            <div className="space-y-6">
              <div className="h-12 w-12 rounded-full border border-background/20 flex items-center justify-center">
                <Info size={20} />
              </div>
              <h2 className="text-4xl font-black uppercase italic leading-none">
                Measurement <br /> Protocol.
              </h2>
              <p className="text-sm font-medium opacity-60 leading-relaxed italic uppercase tracking-tighter">
                Our archive is built on ISO standard 19407. Note that anatomical
                variations may require a ±0.5 scale adjustment. Always measure
                mid-day for peak accuracy.
              </p>
            </div>

            <div className="space-y-4 border-l border-background/10 pl-0 md:pl-12">
              <div className="space-y-1">
                <p className="text-[10px] font-black uppercase opacity-40">
                  Engineering Status
                </p>
                <p className="text-xl font-bold italic uppercase tracking-widest">
                  Verified 2026
                </p>
              </div>
              <div className="space-y-1">
                <p className="text-[10px] font-black uppercase opacity-40">
                  Standardization
                </p>
                <p className="text-xl font-bold italic uppercase tracking-widest">
                  Global ISO/TS
                </p>
              </div>
              <button className="pt-6 text-brand font-black uppercase tracking-widest text-[10px] flex items-center gap-2 hover:gap-4 transition-all">
                Download Full PDF Specs <ArrowRight size={14} />
              </button>
            </div>
          </div>
        </div>
      </section>
    </div>
  );
}
